/**
 * Integration tests against real databases (docker/docker-compose.yml).
 * They verify that the SQL generated by each client actually runs on the server
 * and that introspection reads back what was created.
 *
 * Run: npm run test:db:up && npm run test:integration
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';

import { hasCapability } from '../../src/main/libs/db/core/contracts';
import { getTestEngines } from './helpers/engines';

const TABLE = 'it_products';
const VIEW = 'it_cheap_products';

for (const engine of getTestEngines()) {
   describe.sequential(`${engine.name} integration`, () => {
      const { schema, types, customizations: features } = engine;
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      let client: any;

      const field = (props: Record<string, unknown>) => ({
         schema,
         table: TABLE,
         alias: props.name,
         tableAlias: TABLE,
         orgTable: TABLE,
         orgName: props.name,
         nullable: false,
         unsigned: false,
         zerofill: false,
         default: null as string,
         numScale: null as number,
         ...props
      });

      const fields = {
         id: field({ name: 'id', type: types.int, autoIncrement: features.autoIncrement }),
         name: field({ name: 'name', type: types.varchar, charLength: 100, nullable: true }),
         price: field({ name: 'price', type: types.decimal, numLength: 10, numScale: 2, default: '0' })
      };

      const columnNames = async () => {
         const columns: { name: string }[] = await client.getTableColumns({ schema, table: TABLE });
         return columns.map(c => c.name.toLowerCase());
      };

      const dropIfExists = async (sql: string) => {
         try {
            await client.raw(sql);
         }
         catch (_) {}
      };

      const q = (id: string) => (engine.name === 'mysql' || engine.name === 'maria') ? `\`${id}\`` : `"${id}"`;
      const qualified = (id: string) => engine.name === 'firebird' ? q(id) : `${q(schema)}.${q(id)}`;

      beforeAll(async () => {
         client = await engine.connect();
         if (features.views) await dropIfExists(`DROP VIEW ${qualified(VIEW)}`);
         await dropIfExists(`DROP TABLE ${qualified(TABLE)}`);
      });

      afterAll(async () => {
         if (client) {
            if (features.views) await dropIfExists(`DROP VIEW ${qualified(VIEW)}`);
            await dropIfExists(`DROP TABLE ${qualified(TABLE)}`);
            await client.destroy();
         }
         engine.cleanup?.();
      });

      it('pings the server', async () => {
         await expect(client.ping()).resolves.toBeDefined();
      });

      it('reads the server collations', async ({ skip }) => {
         if (!features.collations) skip();
         // MariaDB 10.10+ returns rows with NULL Charset/Id/Default (uca1400_*)
         const collations: { collation: string }[] = await client.getCollations();
         expect(collations.length).toBeGreaterThan(0);
      });

      it('creates a table', async () => {
         await client.createTable({
            schema,
            fields: [fields.id, fields.name, fields.price],
            indexes: [{ name: 'PRIMARY', fields: ['id'], type: 'PRIMARY' }],
            foreigns: [],
            checks: [],
            options: { name: TABLE, comment: 'integration', collation: 'utf8mb4_general_ci', engine: 'InnoDB' }
         });

         expect(await columnNames()).toEqual(['id', 'name', 'price']);
      });

      it('inserts and selects rows with the query builder', async () => {
         // Multi-row insert, like "insert fake rows" (ipc-handlers/tables.ts)
         await client.schema(schema).into(TABLE).insert([
            { id: 1, name: '\'apple\'', price: 1.5 },
            { id: 2, name: '\'banana\'', price: 20 }
         ]).run();

         const { rows } = await client.select('*').schema(schema).from(TABLE).orderBy({ id: 'ASC' }).run({ schema });

         expect(rows).toHaveLength(2);
         expect(rows.map((r: Record<string, unknown>) => r.name ?? r.NAME)).toEqual(['apple', 'banana']);
      });

      it('updates and deletes rows with the query builder', async () => {
         // The builder quotes object keys itself and expects the operator in the value (same as ipc-handlers/tables.ts)
         // With limit, like "update table cell" (ipc-handlers/tables.ts)
         await client.update({ name: '= \'pear\'' }).schema(schema).from(TABLE).where({ id: '= 2' }).limit(1).run();
         // With limit, like "delete table rows" (ipc-handlers/tables.ts)
         await client.schema(schema).delete(TABLE).where({ id: '= 1' }).limit(1).run();

         const { rows } = await client.select('*').schema(schema).from(TABLE).run({ schema });

         expect(rows).toHaveLength(1);
         expect(rows[0].name ?? rows[0].NAME).toBe('pear');
      });

      it('alters the table (add + rename column) preserving data', async () => {
         const stock = field({ name: 'stock', type: types.int, default: '0', after: 'price' });
         const title = { ...fields.name, name: 'title', orgName: 'name', charLength: 150 };

         await client.alterTable({
            schema,
            table: TABLE,
            additions: [stock],
            changes: [title],
            deletions: [],
            tableStructure: {
               name: TABLE,
               fields: [fields.id, title, fields.price, stock],
               foreigns: [],
               indexes: [{ name: 'PRIMARY', fields: ['id'], type: 'PRIMARY' }]
            },
            indexChanges: { additions: [], changes: [], deletions: [] },
            foreignChanges: { additions: [], changes: [], deletions: [] },
            checkChanges: { additions: [], changes: [], deletions: [] },
            options: {}
         });

         expect((await columnNames()).sort()).toEqual(['id', 'price', 'stock', 'title']);

         const { rows } = await client.select('*').schema(schema).from(TABLE).run({ schema });
         expect(rows[0].title ?? rows[0].TITLE).toBe('pear');
      });

      it('creates, reads and drops a view', async ({ skip }) => {
         if (!features.views || !features.viewAdd) skip();

         await client.createView({
            schema,
            name: VIEW,
            algorithm: 'UNDEFINED',
            definer: '',
            security: 'DEFINER',
            updateOption: '',
            sql: `SELECT * FROM ${qualified(TABLE)} WHERE ${q('price')} < 100`
         });

         const info = await client.getViewInformations({ schema, view: VIEW });
         expect(info.name.toLowerCase()).toBe(VIEW);

         await client.dropView({ schema, view: VIEW });
      });

      it('alters a materialized view', async ({ skip }) => {
         if (!hasCapability(client, 'materializedViews')) skip();
         const mv = { schema, algorithm: '', definer: '', security: '', updateOption: '' };

         await client.createMaterializedView({ ...mv, name: 'it_mv', sql: `SELECT * FROM ${qualified(TABLE)}` });
         try {
            await client.alterMaterializedView({ view: { ...mv, name: 'it_mv_renamed', oldName: 'it_mv', sql: `SELECT ${q('id')} FROM ${qualified(TABLE)}` } });

            const info = await client.getMaterializedViewInformations({ schema, view: 'it_mv_renamed' });
            expect(info.name).toBe('it_mv_renamed');
            expect(info.sql).not.toContain('price');
         }
         finally {
            await dropIfExists(`DROP MATERIALIZED VIEW IF EXISTS ${qualified('it_mv')}`);
            await dropIfExists(`DROP MATERIALIZED VIEW IF EXISTS ${qualified('it_mv_renamed')}`);
         }
      });

      // #955: DECIMAL(12,2) parameters and return types were read back as DECIMAL(12) / DECIMAL and saved so
      it('keeps the scale of decimal routine parameters and return types when saving them back', async ({ skip }) => {
         if (engine.name !== 'mysql' && engine.name !== 'maria') skip();
         const common = { schema, definer: '', deterministic: true, dataAccess: 'CONTAINS SQL', security: 'DEFINER', comment: '' };
         const amount = { _antares_id: '1', name: 'amount', type: 'DECIMAL', length: '12,2', context: 'IN' };

         try {
            await client.createRoutine({ ...common, name: 'it_proc_dec', parameters: [amount], sql: 'BEGIN\n  SELECT amount;\nEND' });
            const proc = await client.getRoutineInformations({ schema, routine: 'it_proc_dec' });
            expect(proc.parameters).toMatchObject([{ name: 'amount', type: 'DECIMAL', length: '12,2' }]);

            await client.alterRoutine({ routine: { ...common, ...proc, oldName: 'it_proc_dec' } });
            expect((await client.getRoutineInformations({ schema, routine: 'it_proc_dec' })).parameters[0].length).toBe('12,2');

            await client.createFunction({ ...common, name: 'it_func_dec', parameters: [amount], returns: 'DECIMAL', returnsLength: '12,2', sql: 'BEGIN\n  RETURN amount;\nEND' });
            const func = await client.getFunctionInformations({ schema, func: 'it_func_dec' });
            expect(func).toMatchObject({ returns: 'DECIMAL', returnsLength: '12,2', parameters: [{ length: '12,2' }] });

            await client.alterFunction({ func: { ...common, ...func, oldName: 'it_func_dec' } });
            expect(await client.getFunctionInformations({ schema, func: 'it_func_dec' })).toMatchObject({ returnsLength: '12,2', parameters: [{ length: '12,2' }] });
         }
         finally {
            await dropIfExists(`DROP PROCEDURE IF EXISTS ${qualified('it_proc_dec')}`);
            await dropIfExists(`DROP FUNCTION IF EXISTS ${qualified('it_func_dec')}`);
         }
      });

      // #927: triggers written by hand (lowercase, unquoted table) could not be opened on SQLite
      it('reads a trigger created by a query', async ({ skip }) => {
         if (engine.name !== 'sqlite') skip();

         await client.raw(`create TRIGGER it_trg_upd after\nupdate on ${TABLE} for each row begin\nupdate ${TABLE}\nset\n  name = 'x'\nwhere\n  id = old.id;\nend;`, { split: false });
         try {
            const info = await client.getTriggerInformations({ schema, trigger: 'it_trg_upd' });
            expect(info).toMatchObject({ name: 'it_trg_upd', table: TABLE, activation: 'AFTER', event: 'UPDATE' });
            expect(info.sql).toMatch(/^begin[\s\S]*end$/);
         }
         finally {
            await dropIfExists(`DROP TRIGGER ${qualified('it_trg_upd')}`);
         }
      });

      it('drops the table', async () => {
         await client.dropTable({ schema, table: TABLE });

         const structure = await client.getStructure(new Set([schema]));
         const tables = structure.flatMap((s: { tables: { name: string }[] }) => s.tables.map(t => t.name.toLowerCase()));
         expect(tables).not.toContain(TABLE);
      });
   });
}
